tfunction _checkIfMatchHasIndexes(matchStage) {\n\n\t\t\t\t\tif (typeof matchStage !== 'object' || Object.keys(matchStage).length === 0) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\n\t\t\t\t\tvar matchKeys = Object.keys(matchStage);\n\t\t\t\t\tfor (var i = 0; i < matchKeys.length; i++) {\n\t\t\t\t\t\tvar key = matchKeys[i];\n\t\t\t\t\t\tif ((key.indexOf('_buildfire.index') > -1)) {\n\t\t\t\t\t\t\treturn true;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\n\t\t\t\tfunction _findFirstGeoNearStage(stages) {\n\n\t\t\t\t\tif (stages && stages.length === 0) {\n\t\t\t\t\t\treturn null;\n\t\t\t\t\t}\n\n\t\t\t\t\tfor (var i = 0; i < stages.length; i++) {\n\t\t\t\t\t\tvar stage = stages[i];\n\n\t\t\t\t\t\tif (typeof stage !== 'object') {\n\t\t\t\t\t\t\tcontinue;\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\tif (stage.$geoNear && typeof stage.$geoNear === 'object') {\n\t\t\t\t\t\t\treturn { $geoNear: stage.$geoNear, index: i };\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\n\t\t\t\t\treturn null;\n\t\t\t\t}\n\n\t\t\t\tfunction _checkIfGeoNearStagesHasRightKey(stages) {\n\t\t\t\t\t// key : Specify the geospatial indexed field to use when calculating the distance.\n\n\t\t\t\t\tfor (var i = 0; i < stages.length; i++) {\n\t\t\t\t\t\tvar stage = stages[i];\n\n\t\t\t\t\t\tif (typeof stage !== 'object') {\n\t\t\t\t\t\t\tcontinue;\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\tif (stage.$geoNear && (typeof stage.$geoNear !== 'object' || !stage.$geoNear.key ||  !stage.$geoNear.key.endsWith('_buildfire.geo'))) {\n\t\t\t\t\t\t\treturn false;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\n\t\t\t\tif (!params.pipelineStages) {\n\t\t\t\t\tcallback('pipelineStages is required property for aggregation', null);\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\n\t\t\t\tif (!Array.isArray(params.pipelineStages)) {\n\t\t\t\t\tcallback('pipelineStages property should be an array of your pipeline stages', null);\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\n\t\t\t\tvar geoStage = _findFirstGeoNearStage(params.pipelineStages);\n\n\t\t\t\tif (geoStage) {\n\t\t\t\t\tif (geoStage.index !== 0) {\n\t\t\t\t\t\tcallback('$geoNear should be first stage of pipeline', null);\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\n\t\t\t\t\tif (!_checkIfGeoNearStagesHasRightKey(params.pipelineStages)) {\n\t\t\t\t\t\tcallback('$geoNear stages doesn\\'t have the right geospatial indexed field name for key option', null);\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\t// check $match stage should first stage of pipeline\n\t\t\t\t\tif (typeof params.pipelineStages[0] !== 'object' || !params.pipelineStages[0].$match) {\n\t\t\t\t\t\tcallback('$match stage should be first stage of pipeline', null);\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\n\t\t\t\t\tif (!_checkIfMatchHasIndexes(params.pipelineStages[0].$match)) {\n\t\t\t\t\t\tcallback('$match stage should has at least one of the buildfire indexes', null);\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t}\n\n\t\t\t\treturn true;\n\t\t\t}\n\n\t\t\t// these validation not used  for current state, we handle that on server side\n\t\t\t// if (!validate()) {\n\t\t\t//     return;\n\t\t\t// }\n\n\n\t\t\tvar p = new Packet(null, 'publicData.aggregate', {tag: tag, obj: params});\n\t\t\tbuildfire._sendPacket(p, function (err, result) {\n\t\t\t\tcallback(err, result);\n\t\t\t});\n\t\t}\n\t\t/// ref:\n\t\t, onUpdate: function (callback, allowMultipleHandlers) {\n\t\t\treturn buildfire.eventManager.add('publicDataOnUpdate', callback, allowMultipleHandlers);\n\t\t}\n\t\t, triggerOnUpdate: function (obj) {\n\t\t\tbuildfire.eventManager.trigger('publicDataOnUpdate', obj);\n\t\t}\n\t\t/// ref:\n\t\t, onRefresh: function (callback, allowMultipleHandlers) {\n\t\t\treturn buildfire.eventManager.add('publicDataOnRefresh', callback, allowMultipleHandlers);\n\t\t}\n\t\t, triggerOnRefresh: function (obj) {\n\t\t\tbuildfire.eventManager.trigger('publicDataOnRefresh', obj);\n\t\t}\n\t\t/// ref:\n\t\t, disableRefresh: function () {\n\t\t\tvar p = new Packet(null, 'publicData.disableRefresh');\n\t\t\tbuildfire._sendPacket(p);\n\t\t}\n\t}\n\t/**\n\t * Drop data: an app-wide \"drop box\". Anyone can insert into it — no user needs to be logged in — while every\n\t * other operation needs the app's write key, which the app supplies. Records are kept for 30 days at most.\n\t *\n\t * Every method takes (…, tag, options, callback); tag and options may be left out:\n\t *   buildfire.dropData.insert({ ...data }, 'tagName', { checkDuplicate, expiresInMinutes }, (err, result) => {});\n\t */\n\t, dropData: {\n\t\t// (tag, options, callback) with tag and/or options left out\n\t\t_args: function (tag, options, callback) {\n\t\t\tif (typeof (tag) == 'function') {\n\t\t\t\tcallback = tag;\n\t\t\t\ttag = '';\n\t\t\t\toptions = {};\n\t\t\t} else if (typeof (options) == 'function') {\n\t\t\t\tcallback = options;\n\t\t\t\toptions = {};\n\t\t\t}\n\t\t\treturn {tag: tag || '', options: options || {}, callback: typeof (callback) == 'function' ? callback : function () {}};\n\t\t}\n\t\t, _send: function (cmd, data, callback) {\n\t\t\tbuildfire._sendPacket(new Packet(null, 'dropData.' + cmd, data), callback);\n\t\t}\n\t\t/// options: { checkDuplicate?: refuse the insert when the tag already has a record,\n\t\t///            expiresInMinutes?: remove the record that many minutes after it is inserted (result.expiresOn) }\n\t\t, insert: function (obj, tag, options, callback) {\n\t\t\tvar args = buildfire.dropData._args(tag, options, callback);\n\t\t\tif (!obj || typeof (obj) != 'object' || Array.isArray(obj))\n\t\t\t\treturn args.callback({'code': 'error', 'message': 'the data should be an object'}, null);\n\n\t\t\tvar data = {tag: args.tag, obj: obj};\n\t\t\tif (args.options.checkDuplicate) data.checkDuplicate = true;\n\t\t\tif (args.options.expiresInMinutes !== undefined && args.options.expiresInMinutes !== null) data.expiresInMinutes = args.options.expiresInMinutes;\n\t\t\tbuildfire.dropData._send('insert', data, args.callback);\n\t\t}\n\t\t/// id: one record's id, or an array of ids (up to 50)\n\t\t, getById: function (id, tag, options, callback) {\n\t\t\tvar args = buildfire.dropData._args(tag, options, callback);\n\t\t\tbuildfire.dropData._send('get', Array.isArray(id) ? {tag: args.tag, ids: id} : {tag: args.tag, id: id}, args.callback);\n\t\t}\n\t\t/// searchOptions: { filter, sort, page, pageSize, skip, limit, recordCount, fields } as publicData.search takes them\n\t\t, search: function (searchOptions, tag, options, callback) {\n\t\t\tvar args = buildfire.dropData._args(tag, options, callback);\n\t\t\tif (!searchOptions || typeof (searchOptions) != 'object') searchOptions = {};\n\t\t\tif (!searchOptions.filter) searchOptions.filter = {};\n\t\t\tbuildfire.dropData._send('search', {tag: args.tag, obj: searchOptions}, args.callback);\n\t\t}\n\t\t/// params: { pipelineStages: [...] }, the first a $match on a buildfire index\n\t\t, aggregate: function (params, tag, options, callback) {\n\t\t\tvar args = buildfire.dropData._args(tag, options, callback);\n\t\t\tif (!params || typeof (params) != 'object') params = {};\n\t\t\tbuildfire.dropData._send('aggregate', {tag: args.tag, obj: params}, args.callback);\n\t\t}\n\t\t/// options: { id?: replace that record (creating it when it is not there); without it a new record is inserted }\n\t\t, save: function (obj, tag, options, callback) {\n\t\t\tvar args = buildfire.dropData._args(tag, options, callback);\n\t\t\tbuildfire.dropData._send('save', {tag: args.tag, id: args.options.id, obj: obj}, args.callback);\n\t\t}\n\t\t, update: function (id, obj, tag, options, callback) {\n\t\t\tvar args = buildfire.dropData._args(tag, options, callback);\n\t\t\tbuildfire.dropData._send('update', {tag: args.tag, id: id, obj: obj}, args.callback);\n\t\t}\n\t\t, searchAndUpdate: function (search, obj, tag, options, callback) {\n\t\t\tvar args = buildfire.dropData._args(tag, options, callback);\n\t\t\tbuildfire.dropData._send('searchAndUpdate', {tag: args.tag, search: search, obj: obj}, args.ca